window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-8c495c2df52d2c54"]={"versions": [{"id": "FIG-8c495c2df52d2c54", "releases": ["R4.0.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Aktivitätsdiagramm mit zwei Swimlanes („SE context“ und „OS Scheduler context“) zur Darstellung des Gesamtüberwachungsablaufs im Watchdog Manager (WdgM). Das Diagramm veranschaulicht die funktionale Aufteilung und Datenkopplung zwischen asynchron getriebenen Prüfschritten bei Kontrollpunkt-Erreichung innerhalb einer Supervised Entity (SE) und der zyklischen Auswertung innerhalb der Hauptfunktion im Betriebssystem-Kontext.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Kontexte / Swimlanes</strong>:</li>\n<li><code>SE context</code>: Ausführungskontext der überwachten Entität (Supervised Entity, SE), initiiert durch den Aufruf von <code>WdgM_CheckpointReached()</code>.</li>\n<li><code>OS Scheduler context</code>: Periodischer Ausführungskontext des Betriebssystems, initiiert durch den Aufruf von <code>WdgM_MainFunction()</code>.</li>\n<li><strong>Aktivitäten im SE-Kontext</strong>:</li>\n<li><code>Increment Alive Indication Counter of Checkpoint</code>: Erhöht den Alive-Zähler bei Kontrollpunkten.</li>\n<li><code>Deadline Supervision of SE</code>: Prüft die Einhaltung von Zeitgrenzen zwischen Kontrollpunkten.</li>\n<li><code>Logical Supervision of SE</code>: Prüft die korrekte Ausführungsreihenfolge (Kontrollfluss).</li>\n<li><strong>Aktivitäten im OS-Scheduler-Kontext</strong>:</li>\n<li>Schleife <code>For each SE</code>:</li>\n<li><code>Alive Supervision of SE</code>: Bewertet die Alive-Zähler der jeweiligen SE gegen konfigurierte Schwellwerte.</li>\n<li><code>Determine the Local Supervision Status of SE</code>: Ermittelt den lokalen Überwachungsstatus (<code>Local Supervision Status</code>) pro SE.</li>\n<li><code>Determine Global Supervision Status</code>: Berechnet aus den lokalen Stati den systemweiten Zustand.</li>\n<li><code>Handle errors</code>: Führt Fehlerbehandlungsroutinen bei Statusverschlechterungen aus.</li>\n<li><code>Set condition for HW watchdog triggering</code>: Bereitet die Ansteuerung bzw. Trigger-Bedingung für den Hardware-Watchdog-Treiber vor.</li>\n<li><strong>Daten- und Zustandsobjekte</strong>:</li>\n<li><code>Alive Indication Counters</code>: Zählerdaten, geschrieben durch <code>Increment Alive Indication Counter of Checkpoint</code>, gelesen durch <code>Alive Supervision of SE</code>.</li>\n<li><code>Result of each Deadline Supervision of SE (correct/incorrect)</code>: Bewertungsergebnis der Deadline-Überwachung, übergeben an die lokale Statusermittlung.</li>\n<li><code>Result of each Logical Supervision of SE (correct/incorrect)</code>: Bewertungsergebnis der logischen Überwachung, übergeben an die lokale Statusermittlung.</li>\n<li><code>Result of each Alive Supervision of SE (correct/incorrect)</code>: Zwischenergebnis der Alive-Überwachung im Scheduler-Kontext.</li>\n<li><code>Local Supervision Status of SE (state)</code>: Lokaler Zustand pro SE (grün umrandetes Zustandsobjekt).</li>\n<li><code>Global Supervision Status (state)</code>: Globaler Zustand des Watchdog Managers (rot umrandetes Zustandsobjekt).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li><strong>Ereignisgesteuerter Ablauf im SE-Kontext (<code>WdgM_CheckpointReached()</code>)</strong>:</li>\n</ol>\n<ul class=\"fig-list\">\n<li>Startet am initialen Knoten im <code>SE context</code>.</li>\n<li>Inkrementiert den Zähler in <code>Alive Indication Counters</code>.</li>\n<li>Führt sequenziell die <code>Deadline Supervision of SE</code> aus und aktualisiert das Datenobjekt <code>Result of each Deadline Supervision of SE (correct/incorrect)</code>.</li>\n<li>Führt sequenziell die <code>Logical Supervision of SE</code> aus und aktualisiert das Datenobjekt <code>Result of each Logical Supervision of SE (correct/incorrect)</code>.</li>\n<li>Erreicht den Endknoten der Kontrollpunktbehandlung.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Zyklischer Ablauf im Scheduler-Kontext (<code>WdgM_MainFunction()</code>)</strong>:</li>\n</ol>\n<ul class=\"fig-list\">\n<li>Startet am initialen Knoten im <code>OS Scheduler context</code>.</li>\n<li>Iteriert über jede Supervised Entity (<code>For each SE</code>):</li>\n<li>Wertet <code>Alive Indication Counters</code> in der Aktivität <code>Alive Supervision of SE</code> aus und erzeugt <code>Result of each Alive Supervision of SE (correct/incorrect)</code>.</li>\n<li>Führt die Ergebnisse der drei Überwachungsmechanismen (Alive, Deadline, Logical) in <code>Determine the Local Supervision Status of SE</code> zusammen.</li>\n<li>Schreibt den resultierenden Zustand in <code>Local Supervision Status of SE (state)</code>.</li>\n<li>Führt nach Durchlauf aller SEs <code>Determine Global Supervision Status</code> aus und setzt <code>Global Supervision Status (state)</code>.</li>\n<li>Führt <code>Handle errors</code> aus.</li>\n<li>Setzt über <code>Set condition for HW watchdog triggering</code> die Hardware-Trigger-Bedingung und endet am Ablaufendknoten.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li>Das Diagramm definiert normativ die funktionale Entkopplung: Zeitkritische Kontrollpunktmeldungen (<code>WdgM_CheckpointReached</code>) führen keine globale Zustandskonsolidierung durch, sondern persistieren Zähler und Prüfresultate.</li>\n<li>Die Auswertung der Alive-Zähler sowie die Aggregation zum lokalen und globalen Zustand sind zwingend in <code>WdgM_MainFunction</code> gekapselt.</li>\n<li>Implementierer müssen thread-sichere Zugriffe auf die geteilten Datenobjekte (<code>Alive Indication Counters</code>, <code>Result of each Deadline Supervision of SE</code>, <code>Result of each Logical Supervision of SE</code>) sicherstellen, da sie nebenläufig im SE- und OS-Kontext manipuliert bzw. gelesen werden.</li>\n</ul>"}, {"id": "FIG-15315dcc0879f2c5", "releases": ["R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Aktivitätsdiagramm mit zwei Swimlanes („SE context“ und „OS Scheduler context“) zur Darstellung des Gesamtüberwachungsablaufs im Watchdog Manager (WdgM). Das Diagramm veranschaulicht die funktionale Aufteilung und Datenkopplung zwischen asynchron getriebenen Prüfschritten bei Kontrollpunkt-Erreichung innerhalb einer Supervised Entity (SE) und der zyklischen Auswertung innerhalb der Hauptfunktion im Betriebssystem-Kontext.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Kontexte / Swimlanes</strong>:</li>\n<li><code>SE context</code>: Ausführungskontext der überwachten Entität (Supervised Entity, SE), initiiert durch den Aufruf von <code>WdgM_CheckpointReached()</code>.</li>\n<li><code>OS Scheduler context</code>: Periodischer Ausführungskontext des Betriebssystems, initiiert durch den Aufruf von <code>WdgM_MainFunction()</code>.</li>\n<li><strong>Aktivitäten im SE-Kontext</strong>:</li>\n<li><code>Increment Alive Indication Counter of Checkpoint</code>: Erhöht den Alive-Zähler bei Kontrollpunkten.</li>\n<li><code>Deadline Supervision of SE</code>: Prüft die Einhaltung von Zeitgrenzen zwischen Kontrollpunkten.</li>\n<li><code>Logical Supervision of SE</code>: Prüft die korrekte Ausführungsreihenfolge (Kontrollfluss).</li>\n<li><strong>Aktivitäten im OS-Scheduler-Kontext</strong>:</li>\n<li>Schleife <code>For each SE</code>:</li>\n<li><code>Alive Supervision of SE</code>: Bewertet die Alive-Zähler der jeweiligen SE gegen konfigurierte Schwellwerte.</li>\n<li><code>Determine the Local Supervision Status of SE</code>: Ermittelt den lokalen Überwachungsstatus (<code>Local Supervision Status</code>) pro SE.</li>\n<li><code>Determine Global Supervision Status</code>: Berechnet aus den lokalen Stati den systemweiten Zustand.</li>\n<li><code>Handle errors</code>: Führt Fehlerbehandlungsroutinen bei Statusverschlechterungen aus.</li>\n<li><code>Set condition for HW watchdog triggering</code>: Bereitet die Ansteuerung bzw. Trigger-Bedingung für den Hardware-Watchdog-Treiber vor.</li>\n<li><strong>Daten- und Zustandsobjekte</strong>:</li>\n<li><code>Alive Indication Counters</code>: Zählerdaten, geschrieben durch <code>Increment Alive Indication Counter of Checkpoint</code>, gelesen durch <code>Alive Supervision of SE</code>.</li>\n<li><code>Result of each Deadline Supervision of SE (correct/incorrect)</code>: Bewertungsergebnis der Deadline-Überwachung, übergeben an die lokale Statusermittlung.</li>\n<li><code>Result of each Logical Supervision of SE (correct/incorrect)</code>: Bewertungsergebnis der logischen Überwachung, übergeben an die lokale Statusermittlung.</li>\n<li><code>Result of each Alive Supervision of SE (correct/incorrect)</code>: Zwischenergebnis der Alive-Überwachung im Scheduler-Kontext.</li>\n<li><code>Local Supervision Status of SE (state)</code>: Lokaler Zustand pro SE (grün umrandetes Zustandsobjekt).</li>\n<li><code>Global Supervision Status (state)</code>: Globaler Zustand des Watchdog Managers (rot umrandetes Zustandsobjekt).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li><strong>Ereignisgesteuerter Ablauf im SE-Kontext (<code>WdgM_CheckpointReached()</code>)</strong>:</li>\n</ol>\n<ul class=\"fig-list\">\n<li>Startet am initialen Knoten im <code>SE context</code>.</li>\n<li>Inkrementiert den Zähler in <code>Alive Indication Counters</code>.</li>\n<li>Führt sequenziell die <code>Deadline Supervision of SE</code> aus und aktualisiert das Datenobjekt <code>Result of each Deadline Supervision of SE (correct/incorrect)</code>.</li>\n<li>Führt sequenziell die <code>Logical Supervision of SE</code> aus und aktualisiert das Datenobjekt <code>Result of each Logical Supervision of SE (correct/incorrect)</code>.</li>\n<li>Erreicht den Endknoten der Kontrollpunktbehandlung.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Zyklischer Ablauf im Scheduler-Kontext (<code>WdgM_MainFunction()</code>)</strong>:</li>\n</ol>\n<ul class=\"fig-list\">\n<li>Startet am initialen Knoten im <code>OS Scheduler context</code>.</li>\n<li>Iteriert über jede Supervised Entity (<code>For each SE</code>):</li>\n<li>Wertet <code>Alive Indication Counters</code> in der Aktivität <code>Alive Supervision of SE</code> aus und erzeugt <code>Result of each Alive Supervision of SE (correct/incorrect)</code>.</li>\n<li>Führt die Ergebnisse der drei Überwachungsmechanismen (Alive, Deadline, Logical) in <code>Determine the Local Supervision Status of SE</code> zusammen.</li>\n<li>Schreibt den resultierenden Zustand in <code>Local Supervision Status of SE (state)</code>.</li>\n<li>Führt nach Durchlauf aller SEs <code>Determine Global Supervision Status</code> aus und setzt <code>Global Supervision Status (state)</code>.</li>\n<li>Führt <code>Handle errors</code> aus.</li>\n<li>Setzt über <code>Set condition for HW watchdog triggering</code> die Hardware-Trigger-Bedingung und endet am Ablaufendknoten.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li>Das Diagramm definiert normativ die funktionale Entkopplung: Zeitkritische Kontrollpunktmeldungen (<code>WdgM_CheckpointReached</code>) führen keine globale Zustandskonsolidierung durch, sondern persistieren Zähler und Prüfresultate.</li>\n<li>Die Auswertung der Alive-Zähler sowie die Aggregation zum lokalen und globalen Zustand sind zwingend in <code>WdgM_MainFunction</code> gekapselt.</li>\n<li>Implementierer müssen thread-sichere Zugriffe auf die geteilten Datenobjekte (<code>Alive Indication Counters</code>, <code>Result of each Deadline Supervision of SE</code>, <code>Result of each Logical Supervision of SE</code>) sicherstellen, da sie nebenläufig im SE- und OS-Kontext manipuliert bzw. gelesen werden.</li>\n</ul>"}], "trans": [{"from": "FIG-8c495c2df52d2c54", "to": "FIG-15315dcc0879f2c5", "fr": "R4.0.3", "tr": "R4.1.3", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
